public class Same_describeTo_TriageGen1Test {

    @Test
    public void testDescribeTo() {
        // Arrange
        Object wanted = "testObject";
        Same same = new Same(wanted);
        Description description = Mockito.mock(Description.class);

        // Act
        same.describeTo(description);

        // Assert
        // Since appendQuoting is a private method in the same class, 
        // we verify the sequence of calls to the description object.
        // We assume appendQuoting calls description.appendText("'") or similar.
        // Based on the code provided, we verify the explicit appendText calls.

        inOrder(description).verify(description).appendText("same(");
        // appendQuoting(description) is called first
        // appendText(wanted.toString()) is called second
        // appendQuoting(description) is called third
        description.appendText(")"); 

        // To ensure full coverage of the logic provided in the snippet:
        // We verify the specific string concatenation pattern.
        verify(description).appendText("same(");
        verify(description).appendText(wanted.toString());
        verify(description).appendText(")");
    }

    @Test
    public void testDescribeToWithNullWanted() {
        // Arrange
        // Testing with null to see if wanted.toString() throws or handles it
        // In standard Java, null.toString() throws NullPointerException
        Same same = new Same(null);
        Description description = Mockito.mock(Description.class);

        // Act & Assert
        try {
            same.describeTo(description);
        } catch (NullPointerException e) {
            // Expected behavior if wanted is null and toString() is called
        }
    }
}
